package io.tradeops.transaction;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/transactions") public class TransactionQueryController{private final TransactionQueryService s;public TransactionQueryController(TransactionQueryService x){s=x;}@GetMapping public List<TransactionQueryService.Row> search(@RequestParam(required=false)String search,@RequestParam(required=false)String country){return s.search(search,country);}@GetMapping("/monthly-summary") public List<TransactionQueryService.Month> monthly(){return s.monthly();}}